    "level": "Doktora",
    "code": "SKY947",
    "name": "TÜRKİYE'DE DEMOKRASİNİN GELİŞİMİ",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Dr. Öğr. Üyesi CİHAN UZUNÇAYIR",
    "purpose": "Bu dersin amacı, öğrencilerin Türkiye’de demokrasinin tarihsel gelişimini siyasal, toplumsal ve ekonomik boyutlarıyla bütüncül bir şekilde kavramasını sağlamaktır. Öğrenciler Osmanlı’dan günümüze demokrasi deneyiminin temel dinamiklerini, kırılma noktalarını, kurumsal dönüşümlerini ve toplumsal etkilerini analiz edebilme becerisi kazanacaktır. Ders, öğrencilere tarihsel veriler üzerinden eleştirel düşünme, siyasal süreçleri yorumlama ve Türkiye’deki demokratikleşme tartışmalarını bilimsel bir perspektiften değerlendirme yetisi kazandırmayı amaçlar.",
    "content": "Bu ders, Türkiye’de demokrasinin tarihsel gelişimini Osmanlı modernleşmesinden Cumhuriyet’e, çok partili hayata geçişten günümüz siyasal rejim tartışmalarına kadar uzanan geniş bir çerçevede ele almaktadır. Ders kapsamında önce Osmanlı İmparatorluğu’nda reform hareketleri ve erken anayasal deneyimler incelenmekte; ardından Cumhuriyet’in kuruluş süreci, siyasal ve toplumsal yapıdaki dönüşümler, ekonomik ilişkiler, toplumsal sınıflar ve milliyetçilik akımları değerlendirilmektedir. Çok partili hayata geçiş, muhalefetin kurumsallaşması, iktidar mücadeleleri, laiklik ve din–devlet ilişkileri, devletçilik politikaları, halkçılık anlayışı ve Batılılaşma süreçleri derinlemesine tartışılmakta; ders, Türkiye’de siyasi rejim ve siyasi partilerin tarihsel gelişiminin genel bir değerlendirmesi ile tamamlanmaktadır.",
    "methods": "Ders, yüz yüze anlatım ve öğrenci sunumlarıyla yürütülmektedir.",
    "resources": "Dersin gerçek OBS kaynakları; güncel siyaset bilimi ve kamu yönetimi literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
