    "content": "Türkiye'de yönetsel yapılanma süreçleri; temel kavramsal çerçeve, kuramsal yaklaşımlar, kurumsal yapı, aktörler ve karar süreçleri, karşılaştırmalı çözümleme, kanıt ve veri değerlendirmesi, politika seçenekleri, güncel siyasal ve yönetsel tartışmalar boyutlarıyla ele alınır.",
