    "purpose": "Türk ve İslam temelli yönetim tarzlarını devlet, siyaset, bürokrasi, strateji ve gelenek üzerinden değerlendirmek ve günümüz örneklerini anlamak.",
    "content": "Türk islam yönetim şekillerinin temellerini karşılaştırmalı olarak olarak ele almayıöğrenmek kapsamında incelemeleri değerlendirmek .",
