    "name": "VERGİLEMENİN HUKUKİ TEMELLERİ",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Doç. Dr. ONUR UÇAR",
    "purpose": "Bu ders, vergilemenin anayasal ve yasal dayanaklarını, vergi ödevi, kanunilik ilkesi, mali güç/eşitlik ve ölçülülük gibi temel ilkeler ışığında ileri düzeyde tartışmayı amaçlar. Öğrencilerin vergi hukukunun kavramsal çerçevesini, normlar hiyerarşisi ve yargı içtihatlarıyla ilişkilendirerek eleştirel biçimde analiz etmesi; vergilendirme sürecinin (tarh, tahakkuk, tahsil, uyuşmazlık ve yargı) hak-özgürlük boyutları ve usuli güvenceleriyle birlikte değerlendirmesi hedeflenir. Karşılaştırmalı hukuk ve kamu politikası perspektifleri kullanılarak, vergi normlarının tasarımı ve uygulamasına dair sorunların bilimsel yöntemlerle çözümlenmesine katkı sağlanır",
    "content": "Bu derste vergilemenin hukuki temelleri derinlemesine ele alınmaktadır. Vergi hukukunun kavramsal çerçevesi, normatif kaynakları ve anayasal dayanakları incelenir. Vergileme yetkisi, mali güce göre vergilendirme ve kanunilik ilkesi bağlamında vergi ödevi kavramı tartışılır. Vergi hukukunun genel ilkeleri, vergilendirme sürecinin aşamaları ve idarenin yetkileri üzerinde durulur. Vergi borcunun doğumu, tarh, tebliğ, tahakkuk ve tahsil süreçleri hukuki yönleriyle değerlendirilir. Mükellef hakları, idari uyuşmazlıkların çözüm yolları, vergi yargısının işlevi ve yargı kararlarının bağlayıcılığı ayrıntılı biçimde ele alınır. Karşılaştırmalı hukukta vergilendirme ilkeleri, Avrupa İnsan Hakları Mahkemesi ve Anayasa Mahkemesi kararları ışığında vergilemenin temel haklarla ilişkisi tartışılır. Böylece öğrencilerin, vergilendirmenin hukuki boyutlarını ulusal ve uluslararası düzlemde eleştirel bir bakış açısıyla değerlendirmeleri hedeflenir.",
    "methods": "Dersler yüz yüze ve interaktif bir öğretim yöntemiyle yürütülmektedir.",
    "resources": "Dersin gerçek OBS kaynakları; güncel siyaset bilimi ve kamu yönetimi literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
