    "name": "YÖNLENDİRİCİ VERGİLENDİRME",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Doç. Dr. ONUR UÇAR",
    "purpose": "Bu dersin amacı, vergilendirmenin yalnızca devlet gelirini toplama aracılığı olmadığı; kamu politikası, toplumsal davranış biçimlendirme, çevre, ekonomi ve sosyal adalet gibi alanlarda yönlendirici işlevlerini de nasıl üstlendiğini öğrencilerle derinlemesine tartışmaktır.",
    "content": "Bu dersin içeriğini: vergilendirmenin genel amaçları ve vergilemenin toplumsal yönlendirme işlevi, amaca göre vergileme sınıflandırması ve teorik çerçeveler, \"Toplum mühendisliği” açısından vergileme: devletin yönlendirme stratejisi olarak vergi, yönlendirici vergilendirmenin yöntemleri (muafiyetler, istisnalar, indirim/teşvik, ceza, özel tüketim vergileri gibi araçlar), kullanım alanları: çevre politikaları, sağlık, enerji, ulaşım, sosyal politika vs. hukuki sınırlar: anayasal temel hak ve özgürlüklerle çelişme, iadeler, ölçülülük ilkesi, usulsüzlük riski, vergilendirmenin toplumsal ve ekonomik etkilerinin değerlendirilmesi: eşitsizlik, vergi kaçırma, performans, Türkiye örneğinde yönlendirici vergilendirme uygulamalarının analizi ve karşılaştırmalı değerlendirme, reform önerileri ve geleceğe yönelik tartışmalar: yönlendirici vergilerin adaptasyonu ve eleştirileri konuları kapsar.",
    "methods": "Dersler yüz yüze ve interaktif bir öğretim yöntemiyle yürütülmektedir.",
    "resources": "Dersin gerçek OBS kaynakları; güncel siyaset bilimi ve kamu yönetimi literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
