    "content": "Bu ders; kent ve kentleşme kavramlarını farklı disiplinler açısından ele alarak kent kuramlarını, feodal dönemden sanayi kentine uzanan tarihsel kent tiplerini inceler. Dünyada 19. yüzyıldan günümüze kentleşme süreçleri, II. Dünya Savaşı sonrası gelişmeler ve küreselleşme dönemindeki kentsel dönüşümler değerlendirilir. Kentsel koruma, sürdürülebilirlik ve yenileme politikaları kapsamında kent politikaları irdelenir.",
