    "name": "VERGİLEME İLKELERİ VE POLİTİKALARI",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "instructor": "Doç. Dr. ONUR UÇAR",
    "purpose": "Bu dersin amacı, vergilendirmenin teorik ve normatif temellerini, kamu maliyesi içindeki işlevlerini ve ekonomik-sosyal politikalarla ilişkisini analiz etmektir. Vergi adaleti, mali güç, verimlilik, etkinlik ve yönlendiricilik ilkeleri çerçevesinde, modern vergi sistemlerinin yapısı ve işleyişi değerlendirilir. Ders, öğrencilerin vergilendirme ilkelerini sadece mali değil, aynı zamanda hukuki, siyasal ve toplumsal bağlamda kavrayarak, vergi politikalarının tasarımı ve uygulanmasına yönelik eleştirel düşünme becerileri geliştirmesini amaçlar. Böylece katılımcıların hem akademik hem de kamu politikası üretiminde kullanabilecekleri ileri düzeyde bir analiz yetkinliği kazanmaları hedeflenir.",
    "content": "Bu ders, vergilendirme ilkeleri ve politikalarını ekonomik, hukuki ve toplumsal boyutlarıyla bütüncül biçimde ele alır. Vergi adaleti, mali güç, eşitlik, genellik, kanunilik ve verimlilik gibi klasik ilkelerin teorik temelleri ve çağdaş vergi sistemlerindeki yansımaları incelenir. Vergilendirmenin iktisadi istikrar, gelir dağılımı, büyüme ve yatırım üzerindeki etkileri analiz edilir. Ders kapsamında ayrıca, vergi harcamaları, dolaylı–dolaysız vergi dengesi, çevresel vergiler, dijital ekonomide vergilendirme ve uluslararası vergi rekabeti gibi güncel politika alanları tartışılır. Katılımcılardan, vergi politikalarının tasarımı, uygulanması ve değerlendirilmesine ilişkin eleştirel çözümlemeler geliştirmeleri beklenir. Böylece ders, vergi sistemlerinin kamu politikası, toplumsal adalet ve ekonomik etkinlik arasındaki dengeyi nasıl kurduğunu anlamaya yönelik derin bir perspektif kazandırır.",
    "methods": "Dersler yüz yüze ve interaktif bir öğretim yöntemiyle yürütülmektedir.",
