    "term": "Bahar",
    "instructor": "Doç. Dr. ONUR UÇAR",
    "purpose": "Bu dersin amacı, sürdürülebilir kalkınma ilkeleri çerçevesinde kent yönetiminin dönüşümünü, yönetişim modellerini ve çevresel, ekonomik ile toplumsal sürdürülebilirliği sağlama süreçlerini derinlemesine analiz etmektir. Kentlerin iklim değişikliği, göç, dijitalleşme ve sosyal adalet gibi çok boyutlu sorunlar karşısında nasıl yönetildiği; yerel yönetimlerin, merkezi idarenin, sivil toplumun ve özel sektörün rollerinin nasıl yeniden tanımlandığı tartışılır. Öğrencilerden, sürdürülebilir kent yönetiminin kuramsal temellerini kavrayarak, yenilikçi, katılımcı ve bütüncül politika önerileri geliştirmeleri beklenir. Bu sayede ders, çevre politikaları, akıllı şehir stratejileri ve yerel demokrasi arasındaki ilişkilere dair ileri düzey bir değerlendirme kapasitesi kazandırır.",
    "content": "Bu ders, sürdürülebilirlik ilkeleri temelinde kent yönetiminin kuramsal, yönetsel ve uygulamalı boyutlarını incelemektedir. Kentlerin ekolojik, ekonomik, toplumsal ve yönetsel sürdürülebilirliği arasındaki ilişki bütüncül bir çerçevede ele alınır. Sürdürülebilir kalkınma hedefleri (SKA), çevresel planlama, kentsel dayanıklılık, yeşil altyapı ve akıllı şehir uygulamaları tartışılır. Yerel yönetimlerin ve kent aktörlerinin politika geliştirme, uygulama ve izleme süreçlerindeki rolleri, katılımcı yönetişim yaklaşımları ışığında analiz edilir. İklim değişikliğiyle mücadele, enerji verimliliği, sosyal kapsayıcılık ve dijital dönüşüm gibi temalar kent yönetiminde sürdürülebilirlik ilkesiyle bağlantılı biçimde değerlendirilir. Dersin sonunda öğrencilerden, sürdürülebilir kent yönetimi üzerine eleştirel, yenilikçi ve uygulanabilir stratejiler geliştirmeleri beklenir.",
    "methods": "Dersler yüz yüze ve interaktif bir öğretim yöntemiyle yürütülmektedir.",
    "resources": "Dersin gerçek OBS kaynakları; güncel siyaset bilimi ve kamu yönetimi literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
