      "Kamu yönetimi ve yönetişim yaklaşımlarını karşılaştırır.",
      "Sürdürülebilir kent yönetimi kapsamında uygun siyasal ve yönetsel analiz yaklaşımını uygular.",
      "Sürdürülebilir kent yönetimi bulgularını kurumsal ve toplumsal etkileriyle değerlendirir.",
      "Sürdürülebilir kent yönetimi alanındaki kanıtlara dayalı politika ve yönetim önerileri geliştirir."
